package ro.hsldigitallab.casamia.receiver;

import org.json.JSONObject;
import java.io.*;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import javax.net.ssl.HttpsURLConnection;

final class ApiClient {
    static final class Failure extends IOException {
        final int status;
        Failure(int status, String text) { super(text); this.status = status; }
    }
    static JSONObject call(String base, String token, String route, JSONObject body, String key) throws Exception {
        URL url = new URL(ReceiverRules.baseUrl(base) + "api/index.php?path=" + route);
        HttpsURLConnection c = (HttpsURLConnection) url.openConnection();
        c.setInstanceFollowRedirects(false); c.setConnectTimeout(6000); c.setReadTimeout(8000);
        c.setRequestProperty("Accept", "application/json"); c.setRequestProperty("Cache-Control", "no-store");
        if (!token.isEmpty()) c.setRequestProperty("Authorization", "Bearer " + token);
        if (key != null) c.setRequestProperty("Idempotency-Key", key);
        try {
            if (body != null) {
                byte[] bytes = body.toString().getBytes(StandardCharsets.UTF_8);
                c.setRequestMethod("POST"); c.setDoOutput(true);
                c.setRequestProperty("Content-Type", "application/json; charset=utf-8"); c.setFixedLengthStreamingMode(bytes.length);
                try (OutputStream out = c.getOutputStream()) { out.write(bytes); }
            }
            int status = c.getResponseCode();
            InputStream stream = status >= 200 && status < 300 ? c.getInputStream() : c.getErrorStream();
            if (stream == null) throw new Failure(status, "Serverul nu a confirmat cererea.");
            byte[] bytes;
            try (InputStream in = stream; ByteArrayOutputStream out = new ByteArrayOutputStream()) {
                byte[] b = new byte[4096]; int n;
                while ((n = in.read(b)) != -1) { if (out.size() + n > 1024 * 1024) throw new IOException("Răspuns prea mare."); out.write(b, 0, n); }
                bytes = out.toByteArray();
            }
            JSONObject result;
            try { result = new JSONObject(new String(bytes, StandardCharsets.UTF_8)); }
            catch (Exception e) { throw new Failure(status, "Adresa nu răspunde cu API-ul Casa Mia. Verifică instalarea pe găzduire."); }
            if (status < 200 || status >= 300) throw new Failure(status,
                    result.optString("error", "Cererea nu a fost confirmată (" + status + ")."));
            return result;
        } finally { c.disconnect(); }
    }
}

