package ro.hsldigitallab.casamia.receiver;
import org.junit.Test;
import static org.junit.Assert.*;

public class ReceiverRulesTest {
    @Test public void httpsBaseIsNormalized() { assertEquals("https://restaurant.example/sub/", ReceiverRules.baseUrl(" https://restaurant.example/sub/// ")); }
    @Test public void plaintextAndCredentialUrlsAreRejected() {
        for (String value : new String[]{"http://restaurant.example", "https://user:secret@restaurant.example", "https://restaurant.example/?token=secret", "https://restaurant.example/#secret", "https://restaurant.example:8080", "https://restaurant.example/../"}) {
            assertThrows(IllegalArgumentException.class, () -> ReceiverRules.baseUrl(value));
        }
    }
    @Test public void emptyEstimateIsNotInvented() { assertNull(ReceiverRules.eta(" ")); }
    @Test public void estimateMustBeRealisticPositiveInteger() {
        assertEquals(Integer.valueOf(25), ReceiverRules.eta("25"));
        for (String value : new String[]{"0", "241", "-1", "25.5", "abc"}) assertThrows(IllegalArgumentException.class, () -> ReceiverRules.eta(value));
    }
    @Test public void deliveryRequiresExplicitAreaCheck() { assertThrows(IllegalArgumentException.class, () -> ReceiverRules.acceptance("livrare", false)); ReceiverRules.acceptance("livrare", true); ReceiverRules.acceptance("ridicare", false); }
    @Test public void multipleOrdersKeepTheAlarmAfterFirstAcceptance() {
        assertEquals(2, ReceiverRules.verifiedPending(2, 2, false, true));
        assertEquals(1, ReceiverRules.verifiedPending(1, 1, false, true));
        assertEquals(0, ReceiverRules.verifiedPending(0, 0, false, false));
    }
    @Test public void partialPageDoesNotClearAlarm() { assertEquals(120, ReceiverRules.verifiedPending(120, 100, true, true)); }
    @Test public void malformedResponsesMustNotClearPreviousPendingState() {
        assertThrows(IllegalArgumentException.class, () -> ReceiverRules.verifiedPending(0, 1, false, false));
        assertThrows(IllegalArgumentException.class, () -> ReceiverRules.verifiedPending(0, 0, true, false));
        assertThrows(IllegalArgumentException.class, () -> ReceiverRules.verifiedPending(1, 0, true, true));
        assertThrows(IllegalArgumentException.class, () -> ReceiverRules.verifiedPending(1, 1, false, false));
        assertThrows(IllegalArgumentException.class, () -> ReceiverRules.verifiedPending(-1, 0, false, false));
    }
}

